// Package pgtarget is the copy tool's PostgreSQL side (ADR 0025 step 9): the target database, on
// the server's own storage (its migrations and its writer-locked transactions). Table and column
// names come from the target's catalog, so its statements are built here rather than generated by
// sqlc, which only knows fixed tables.
package pgtarget

import (
	"context"
	"errors"
	"fmt"
	"strings"

	"github.com/lib/pq"

	"github.com/ceffo/critical/api/internal/sqlitecopy"
	"github.com/ceffo/critical/api/internal/storage/postgres"
)

// Target is the PostgreSQL database the copy writes into.
type Target struct{ db *postgres.DB }

var _ sqlitecopy.Target = Target{}

// New returns the target over an open database.
func New(db *postgres.DB) Target { return Target{db: db} }

// conn is the transaction ctx carries (inside InTx), else the pool.
func (t Target) conn(ctx context.Context) postgres.DBTX { return postgres.Conn(ctx, t.db.Pool()) }

// Tables lists every base table of the current schema.
func (t Target) Tables(ctx context.Context) ([]string, error) {
	return t.strings(ctx, `SELECT table_name FROM information_schema.tables
		WHERE table_schema = current_schema() AND table_type = 'BASE TABLE' ORDER BY table_name`)
}

// Migrate applies the server's migrations, in its one locked migration transaction.
func (t Target) Migrate(ctx context.Context) error { return t.db.Migrate(ctx) }

// Applied lists the recorded migrations.
func (t Target) Applied(ctx context.Context) ([]string, error) {
	return t.strings(ctx, `SELECT name FROM schema_migrations ORDER BY name`)
}

// Schema reads the app tables (base tables only, never a view), their columns in order with the identity column, and the foreign
// keys between them, from the catalog of the current schema.
func (t Target) Schema(ctx context.Context) (_ []sqlitecopy.Table, _ []sqlitecopy.ForeignKey, err error) {
	rows, err := t.conn(ctx).QueryContext(ctx, `SELECT c.table_name, c.column_name, c.is_identity = 'YES'
		FROM information_schema.columns c
		JOIN information_schema.tables t ON t.table_schema = c.table_schema AND t.table_name = c.table_name
		WHERE c.table_schema = current_schema() AND t.table_type = 'BASE TABLE'
		  AND c.table_name <> 'schema_migrations'
		ORDER BY c.table_name, c.ordinal_position`)
	if err != nil {
		return nil, nil, err
	}
	defer func() { err = errors.Join(err, rows.Close()) }()
	var tables []sqlitecopy.Table
	for rows.Next() {
		var table, column string
		var identity bool
		if err := rows.Scan(&table, &column, &identity); err != nil {
			return nil, nil, err
		}
		if len(tables) == 0 || tables[len(tables)-1].Name != table {
			tables = append(tables, sqlitecopy.Table{Name: table})
		}
		last := &tables[len(tables)-1]
		last.Columns = append(last.Columns, column)
		if identity {
			last.Identity = column
		}
	}
	if err := rows.Err(); err != nil {
		return nil, nil, err
	}
	fks, err := t.foreignKeys(ctx)
	if err != nil {
		return nil, nil, err
	}
	return tables, fks, nil
}

func (t Target) foreignKeys(ctx context.Context) (_ []sqlitecopy.ForeignKey, err error) {
	rows, err := t.conn(ctx).QueryContext(ctx, `SELECT child.relname, parent.relname
		FROM pg_constraint c
		JOIN pg_class child ON child.oid = c.conrelid
		JOIN pg_class parent ON parent.oid = c.confrelid
		WHERE c.contype = 'f' AND c.connamespace = current_schema()::regnamespace
		ORDER BY 1, 2`)
	if err != nil {
		return nil, err
	}
	defer func() { err = errors.Join(err, rows.Close()) }()
	var fks []sqlitecopy.ForeignKey
	for rows.Next() {
		var fk sqlitecopy.ForeignKey
		if err := rows.Scan(&fk.Table, &fk.References); err != nil {
			return nil, err
		}
		fks = append(fks, fk)
	}
	return fks, rows.Err()
}

// InTx runs fn in one of the server's write transactions (READ COMMITTED, writer lock first). Its
// session time zone is UTC: SQLite stored its timestamps as UTC text without a zone.
func (t Target) InTx(ctx context.Context, fn func(ctx context.Context) error) error {
	return t.db.InTx(ctx, func(ctx context.Context) error {
		if _, err := t.conn(ctx).ExecContext(ctx, `SET LOCAL TIME ZONE 'UTC'`); err != nil {
			return fmt.Errorf("set the time zone: %w", err)
		}
		return fn(ctx)
	})
}

// Count is the number of rows of a table.
func (t Target) Count(ctx context.Context, table string) (int64, error) {
	var n int64
	err := t.conn(ctx).QueryRowContext(ctx, `SELECT count(*) FROM `+pq.QuoteIdentifier(table)).Scan(&n)
	return n, err
}

// Copy streams the rows into the table with COPY FROM STDIN: one statement per table, so the
// foreign keys are checked at its end (an action may name a later action as its transaction head)
// and a remote target costs one round trip per table rather than per row.
func (t Target) Copy(ctx context.Context, table string, columns []string, rows func(emit func(row []any) error) error) (n int64, err error) {
	quoted := make([]string, len(columns))
	for i, c := range columns {
		quoted[i] = pq.QuoteIdentifier(c)
	}
	copyIn := "COPY " + pq.QuoteIdentifier(table) + " (" + strings.Join(quoted, ", ") + ") FROM STDIN"
	stmt, err := t.conn(ctx).PrepareContext(ctx, copyIn)
	if err != nil {
		return 0, err
	}
	defer func() { err = errors.Join(err, stmt.Close()) }()
	err = rows(func(row []any) error {
		if _, err := stmt.ExecContext(ctx, row...); err != nil {
			return err
		}
		n++
		return nil
	})
	if err != nil {
		return 0, err
	}
	if _, err := stmt.ExecContext(ctx); err != nil {
		return 0, err
	}
	return n, nil
}

// MaxID is the highest value of an identity column, 0 for an empty table.
func (t Target) MaxID(ctx context.Context, table, column string) (int64, error) {
	var id int64
	err := t.conn(ctx).QueryRowContext(ctx,
		`SELECT coalesce(max(`+pq.QuoteIdentifier(column)+`), 0) FROM `+pq.QuoteIdentifier(table)).Scan(&id)
	return id, err
}

// SetNextID makes next the identity column's next value.
func (t Target) SetNextID(ctx context.Context, table, column string, next int64) error {
	_, err := t.conn(ctx).ExecContext(ctx,
		`SELECT setval(pg_get_serial_sequence($1, $2), $3, false)`, pq.QuoteIdentifier(table), column, next)
	return err
}

func (t Target) strings(ctx context.Context, query string) (out []string, err error) {
	rows, err := t.conn(ctx).QueryContext(ctx, query)
	if err != nil {
		return nil, err
	}
	defer func() { err = errors.Join(err, rows.Close()) }()
	for rows.Next() {
		var v string
		if err := rows.Scan(&v); err != nil {
			return nil, err
		}
		out = append(out, v)
	}
	return out, rows.Err()
}
